async function buildPlan(goal, mcpClient) {
  const tools = await mcpClient.listTools();
  const resources = await mcpClient.listResources();
  const prompts = await mcpClient.listPrompts();

  const toolNames = new Set(tools.map((t) => t.name));
  const draftSteps = decomposeGoal(goal);

  const plan = draftSteps.map((step) => {
    if (!toolNames.has(step.tool)) {
      return { ...step, status: 'blocked', reason: 'no matching tool found during discovery' };
    }
    return { ...step, status: 'ready' };
  });

  return { plan, resources, prompts };
}

def run_plan(plan, mcp_client):
    i = 0
    while i < len(plan):
        step = plan[i]
        try:
            result = mcp_client.call_tool(step["tool"], step["args"])
        except ToolError as err:
            plan = replan(plan, i, reason=str(err))
            continue

        if not matches_expectation(step, result):
            plan = replan(plan, i, reason="unexpected result")
            continue

        step["result"] = result
        i += 1

    return plan
